/**
 * Slides shown one at a time, paged by the reader (`design/components/carousel.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/carousel.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/carousel'

import {
  MEMBER_PROVIDERS,
  Ref,
  Render,
  Spread,
  agentMember,
  cell,
  derived,
  elementRef,
  isTemplate,
  mergeParts,
  mountEffect,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
  type Each,
  type NodeTemplate,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/carousel.module.css'
import { Button, type ButtonProps } from '../controls/Button'

export interface CarouselSlide {
  id: string
  label: string
  content: NodeTemplate | string
}

/** Slides shown one at a time, paged by the reader: the inputs it takes, by the React member's prop names. */
export interface CarouselProps {
  defaultIndex?: number
  /**
   * The current slide, controlled as in Slider; swiping also calls `onIndexChange`.
   */
  index?: number
  /**
   * Names the carousel, such as "Product tour" rather than "Carousel".
   */
  label: string
  /**
   * Wraps from the first slide to the last and back; when off, the end buttons are disabled.
   */
  loop?: boolean
  nextLabel: string
  /**
   * Accessible names for the previous and next buttons, in the app's language, with no default.
   */
  previousLabel: string
  /**
   * Spoken role names for the region and each slide (default `carousel` and `slide`, the APG's
   * terms); localized hosts pass both or neither.
   */
  roleDescriptions?: { carousel: string; slide: string }
  /**
   * Slides in reading order; an empty list renders nothing, and the page handles it.
   */
  slides: CarouselSlide[]
}

/** Slides shown one at a time, paged by the reader. */
@Component({
  selector: 'pm-carousel',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Render, Spread, Button],
  // prettier-ignore
  template: `@if (e1()) {<section
role="group"
[attr.aria-roledescription]="e2()"
[attr.aria-label]="e3()"
data-member="carousel"
[pmRef]="root"
><!-- viewport -->
<div
[pmSpread]="e4()"
[pmRef]="viewport"
>@for (slide of e5(); track e6(slide); let at = $index) {<!-- slide -->
<div
[pmSpread]="e7(slide, at)"
>@if (e8(slide)) {{{ e9(slide) }}} @else {@if (template(e10(slide))) {<ng-container [pmRender]="e10(slide)" />} @else {{{ e10(slide) }}}}</div>}</div>
<!-- controls -->
<div
[attr.class]="e11()"
[pmRef]="controls"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e12()"
icon="previous"
[label]="e13()"
[disabled]="e14()"
(click)="h2()"
></pm-button>
<!-- rail -->
<span
[attr.class]="e15()"
>@for (slide of e5(); track e6(slide); let at = $index) {<!-- dot -->
<button
[attr.class]="e16()"
type="button"
data-carousel-part="dot"
[attr.aria-label]="e17(slide)"
[attr.aria-current]="e18(at)"
(click)="h3(at)"
></button>}</span>
<pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e12()"
icon="next"
[label]="e19()"
[disabled]="e20()"
(click)="h4()"
></pm-button></div></section>}`,
})
export class Carousel {
  readonly defaultIndex = input<
    Exclude<CarouselProps['defaultIndex'], undefined>,
    CarouselProps['defaultIndex']
  >(0, { transform: (value: CarouselProps['defaultIndex']) => (value === undefined ? 0 : value) })
  /**
   * The current slide, controlled as in Slider; swiping also calls `onIndexChange`.
   */
  readonly index = input<CarouselProps['index']>(undefined)
  /**
   * Names the carousel, such as "Product tour" rather than "Carousel".
   */
  readonly label = input.required<CarouselProps['label']>()
  /**
   * Wraps from the first slide to the last and back; when off, the end buttons are disabled.
   */
  readonly loop = input<Exclude<CarouselProps['loop'], undefined>, CarouselProps['loop']>(false, {
    transform: (value: CarouselProps['loop']) => (value === undefined ? false : value),
  })
  readonly nextLabel = input.required<CarouselProps['nextLabel']>()
  /**
   * Accessible names for the previous and next buttons, in the app's language, with no default.
   */
  readonly previousLabel = input.required<CarouselProps['previousLabel']>()
  /**
   * Spoken role names for the region and each slide (default `carousel` and `slide`, the APG's
   * terms); localized hosts pass both or neither.
   */
  readonly roleDescriptions = input<
    Exclude<CarouselProps['roleDescriptions'], undefined>,
    CarouselProps['roleDescriptions']
  >((() => ({ carousel: 'carousel', slide: 'slide' }))(), {
    transform: (value: CarouselProps['roleDescriptions']) =>
      value === undefined ? (() => ({ carousel: 'carousel', slide: 'slide' }))() : value,
  })
  /**
   * Slides in reading order; an empty list renders nothing, and the page handles it.
   */
  readonly slides = input.required<CarouselProps['slides']>()
  readonly onIndexChange = output<number>({ alias: 'indexChange' })
  protected readonly $ = useMember({
    events: ['indexChange'],
    props: {
      defaultIndex: () => this.defaultIndex(),
      index: () => this.index(),
      label: () => this.label(),
      loop: () => this.loop(),
      nextLabel: () => this.nextLabel(),
      previousLabel: () => this.previousLabel(),
      roleDescriptions: () => this.roleDescriptions(),
      slides: () => this.slides(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly kept = cell(() => this.$p.index ?? this.$p.defaultIndex)
  protected readonly scrolls = cell(() => 0)
  protected readonly sent = cell(() => -1)
  protected readonly moving = cell(() => false)
  protected readonly controls = elementRef<HTMLElement>()
  protected readonly root = elementRef<HTMLElement>()
  protected readonly viewport = elementRef<HTMLElement>()
  protected readonly measurable = derived(
    () => () => this.viewport.value !== null && this.viewport.value.clientWidth > 0,
  )
  protected readonly within = derived(
    () => (at: number) => Math.min(Math.max(at, 0), Math.max(this.$p.slides.length - 1, 0)),
  )
  protected readonly shown = derived(() => this.within.value(this.$p.index ?? this.kept.value))
  protected readonly instant = derived(() => () => {
    const duration =
      this.viewport.value === null
        ? NaN
        : parseFloat(
            getComputedStyle(this.viewport.value).getPropertyValue('--pm-motion-duration-surface'),
          )
    return Number.isNaN(duration) || duration <= 0
  })
  protected readonly travel = derived(() => (to: number) => {
    if (to === this.shown.value) return
    if (this.$p.index === undefined) this.go.value(to, this.instant.value())
    else this.$.emit(this.onIndexChange, 'onIndexChange', to)
  })
  protected readonly resting = derived(
    () => (nearest: number) =>
      this.viewport.value !== null &&
      Math.abs(
        Math.abs(this.viewport.value.scrollLeft) - nearest * this.viewport.value.clientWidth,
      ) <= 1,
  )
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          slideCount: this.$p.slides.length,
          defaultPage: this.$p.index ?? this.$p.defaultIndex,
          loop: this.$p.loop,
          onPageChange: (details) => {
            void (
              this.measurable.value() &&
              details.page !== this.kept.value &&
              ((this.kept.value = details.page),
              details.page !== this.$p.index &&
                this.$.emit(this.onIndexChange, 'onIndexChange', details.page))
            )
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly go = derived(() => (to: number, now: boolean) => {
    this.sent.value = this.scrolls.value
    this.moving.value = true
    this.api.value.scrollTo(to, now)
  })
  protected readonly settle = derived(() => () => {
    if (this.viewport.value === null || !this.measurable.value()) return
    const nearest = this.within.value(
      Math.round(Math.abs(this.viewport.value.scrollLeft) / this.viewport.value.clientWidth),
    )
    if (this.moving.value) {
      if (this.scrolls.value === this.sent.value || !this.resting.value(nearest)) return
      this.moving.value = false
    }
    if (nearest !== this.api.value.page) this.go.value(nearest, true)
  })
  protected readonly template = isTemplate
  private release2: (() => void) | undefined
  private release3: (() => void) | undefined
  private release4: (() => void) | undefined
  private release5: (() => void) | undefined

  constructor() {
    watchEffect(
      () => this.$p.index,
      () => this.effect1(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
    inject(DestroyRef).onDestroy(() => this.release3?.())
    watchEffect(
      () => this.scrolls.value,
      () => this.effect3(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release4?.())
    mountEffect(() => this.effect4())
    inject(DestroyRef).onDestroy(() => this.release5?.())
    mountEffect(() => this.effect5())
  }

  protected e1() {
    return this.$p.slides.length > 0
  }

  protected e2() {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return this.$p.roleDescriptions.carousel
  }

  protected e3() {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return this.$p.label
  }

  protected h1(): void {
    if (!(this.$p.slides.length > 0)) return
    this.scrolls.value += 1
  }

  protected e4() {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return mergeParts(
      { ...this.api.value.getItemGroupProps(), style: undefined, dir: undefined },
      {
        class: styles.viewport,
        tabindex: '0',
        role: 'region',
        'aria-label': this.$p.label,
        'aria-live': undefined,
        onScroll: () => this.h1(),
      },
    )
  }

  e5() {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return this.$p.slides
  }

  protected e6(slide: Each<ReturnType<Carousel['e5']>>) {
    return slide.id
  }

  protected e7(slide: Each<ReturnType<Carousel['e5']>>, at: number) {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return mergeParts(
      { ...this.api.value.getItemProps({ index: at }), style: undefined, dir: undefined },
      {
        class: styles.slide,
        role: 'group',
        'aria-roledescription': this.$p.roleDescriptions.slide,
        'aria-label': slide.label,
        'aria-hidden': undefined,
      },
    )
  }

  protected e8(slide: Each<ReturnType<Carousel['e5']>>) {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return typeof slide.content === 'string'
  }

  protected e9(slide: Each<ReturnType<Carousel['e5']>>) {
    if (!(this.$p.slides.length > 0)) return undefined as never
    if (!(typeof slide.content === 'string')) return undefined as never
    return slide.content
  }

  protected e10(slide: Each<ReturnType<Carousel['e5']>>) {
    if (!(this.$p.slides.length > 0)) return undefined as never
    if (typeof slide.content === 'string') return undefined as never
    return slide.content
  }

  protected e11() {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return styles.controls
  }

  protected e12(): ButtonProps['iconOnly'] {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return true
  }

  protected e13(): ButtonProps['label'] {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return this.$p.previousLabel
  }

  protected e14(): ButtonProps['disabled'] {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return !this.$p.loop && this.shown.value === 0
  }

  protected h2(): void {
    if (!(this.$p.slides.length > 0)) return
    this.travel.value(this.shown.value === 0 ? this.$p.slides.length - 1 : this.shown.value - 1)
  }

  protected e15() {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return styles.rail
  }

  protected e16() {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return styles.dot
  }

  protected e17(slide: Each<ReturnType<Carousel['e5']>>) {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return slide.label
  }

  protected e18(at: number) {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return at === this.shown.value ? true : undefined
  }

  protected h3(at: number): void {
    if (!(this.$p.slides.length > 0)) return
    this.travel.value(at)
  }

  protected e19(): ButtonProps['label'] {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return this.$p.nextLabel
  }

  protected e20(): ButtonProps['disabled'] {
    if (!(this.$p.slides.length > 0)) return undefined as never
    return !this.$p.loop && this.shown.value === this.$p.slides.length - 1
  }

  protected h4(): void {
    if (!(this.$p.slides.length > 0)) return
    this.travel.value(this.shown.value === this.$p.slides.length - 1 ? 0 : this.shown.value + 1)
  }

  private effect1(): void {
    void (
      this.$p.index !== undefined &&
      ((this.kept.value = this.within.value(this.$p.index)),
      this.within.value(this.$p.index) !== this.api.value.page &&
        this.go.value(this.within.value(this.$p.index), this.instant.value()))
    )
  }

  private effect2(): void {
    this.release2?.()
    const run = () => {
      void (
        this.measurable.value() &&
        this.api.value.page !== this.within.value(this.kept.value) &&
        this.go.value(this.within.value(this.kept.value), true)
      )
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.viewport.value]) if (element) resize?.observe(element)
    this.release2 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect3(): void {
    this.release3?.()
    const timer = setTimeout(() => {
      this.settle.value()
    }, 150)
    this.release3 = () => clearTimeout(timer)
  }

  private effect4(): void {
    this.release4?.()
    const run = () => {
      void (
        this.viewport.value !== null &&
        this.viewport.value.getAttribute('tabindex') !== '0' &&
        this.viewport.value.setAttribute('tabindex', '0')
      )
    }
    const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
    for (const element of [this.viewport.value])
      if (element)
        mutation?.observe(element, {
          childList: true,
          characterData: true,
          subtree: true,
          attributeFilter: ['tabindex'],
        })
    this.release4 = () => {
      mutation?.disconnect()
    }
    run()
  }

  private effect5(): void {
    this.release5?.()
    const ran = agentMember({
      member: 'Carousel',
      element: () => this.root.value,
      state: () => ({
        index: this.shown.value,
        slides: this.$p.slides.map((slide) => ({ id: slide.id, label: slide.label })),
      }),
      actions: {
        set: {
          argument: 'number',
          run: (value) =>
            (() => {
              if (!Number.isInteger(value) || value < 0 || value >= this.$p.slides.length) {
                throw new Error(
                  `There is no slide ${value}; the slides run from 0 to ${this.$p.slides.length - 1}.`,
                )
              }
              this.travel.value(value)
            })(),
        },
      },
      withholds: () => this.controls.value,
    })
    this.release5 = () => {
      ran()
    }
  }
}
